// Validate experience report input
const body = $input.first().json;

const required = ['user_id', 'title', 'fault_description', 'solution'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

return {
  user_id: body.user_id,
  title: body.title.trim(),
  fault_description: body.fault_description.trim(),
  solution: body.solution.trim(),
  photos: Array.isArray(body.photos) ? body.photos : (body.photos ? [body.photos] : []),
  machine_type: body.machine_type || '',
  report_id: 'exp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
  created_at: new Date().toISOString(),
};

// Build notification payload for the team leader
const data = $('Validate & Normalize').first().json;

// This payload is ready to send to WeCom/DingTalk/Email webhook
// Replace the notification_url with actual webhook when configuring
return {
  msgtype: 'text',
  text: {
    content: `【新经验报告待审核】\n标题：${data.title}\n提交人ID：${data.user_id}\n故障描述：${data.fault_description.slice(0, 100)}${data.fault_description.length > 100 ? '...' : ''}\n时间：${data.created_at}\n\n请登录系统进行审核。`
  },
  report_id: data.report_id,
  user_id: data.user_id,
  title: data.title,
};
